"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["76599"],{89251(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.geo.importacao.nao_enfileirada","status":503,"titulo":"N\xe3o foi poss\xedvel colocar a carga na fila porque o servi\xe7o est\xe1 sendo encerrado"},"descricao":{"codigo":"uniplus.geo.importacao.nao_enfileirada","requisitos":["UNI-REQ-0534"],"oQueAconteceu":["O pacote foi recebido e conferido, e a execu\xe7\xe3o da carga chegou a ser registrada, mas ela n\xe3o p\xf4de entrar na fila de carga porque o servi\xe7o do Geo est\xe1 sendo desligado. O Geo respondeu **503** com a mensagem \\"N\xe3o foi poss\xedvel colocar a carga na fila porque o servi\xe7o est\xe1 sendo encerrado.\\".","A carga n\xe3o come\xe7ou: a execu\xe7\xe3o registrada fica com falha (\\"Servi\xe7o em desligamento; carga n\xe3o enfileirada.\\"), a base publicada continua na vers\xe3o anterior, a vers\xe3o n\xe3o conta como aplicada e o arquivo recebido \xe9 apagado. A resposta n\xe3o traz o identificador da execu\xe7\xe3o nem o endere\xe7o de acompanhamento dela.","Se a grava\xe7\xe3o da falha tamb\xe9m n\xe3o puder ser feita (por exemplo, banco de dados indispon\xedvel naquele instante), a execu\xe7\xe3o \xe9 encerrada como falha no envio seguinte, que n\xe3o \xe9 recusado por causa dela."],"comoResolver":["Envie o pacote de novo. N\xe3o h\xe1 nada a retomar da primeira tentativa, e a execu\xe7\xe3o com falha n\xe3o impede um novo envio.","Se o erro continuar com o servi\xe7o no ar, avise a equipe de suporte do Uni+."],"ondeAparece":["Envio do pacote (`POST /api/admin/geo/importacoes`), quando o servi\xe7o est\xe1 sendo desligado depois de o pacote ser aceito para a carga"]},"modulo":{"id":"geo","nome":"Geo","assunto":"Importacao"},"origem":{"repositorio":"unifesspa-edu-br/unifesspa-geo-api","commit":"241f54e88e265e24d3723798ba867fe69845ab0c"}}')}}]);